  async function urlParaDataUrl(url) {
    const resposta = await fetch(url);
    const blob = await resposta.blob();
  
    return new Promise((resolve, reject) => {
      const leitor = new FileReader();
      leitor.onloadend = () => resolve(leitor.result);
      leitor.onerror = reject;
      leitor.readAsDataURL(blob);
    });
  }

function normalizarNome(nome) {
  return nome
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase();
}

function extrairTimeDaFoto(src) {
  const match = src?.match(/silhuetas\/([A-Z]{3})\//);
  return match ? match[1] : null;
}

function isSilhueta(src) {
  return src && src.includes("/silhuetas/");
}

/***********************
 * Replace player photos (campo + cards)
 ***********************/
function replacePlayerPhotos() {
  document.querySelectorAll("img.atleta-foto").forEach(img => {
    const container = img.closest(
      "[class*='cartao-atleta'], tr"
    );
    if (!container) return;

    // nome do jogador (funciona em card e campo)
    const nomeEl =
      container.querySelector("[class*='nome-cartao-atleta'] p") ||
      container.querySelector(".texto__30Obi.uppercase__jwRXL");

    const nome = nomeEl?.textContent?.trim();
    if (!nome) return;

    // time
    const time =
      extrairTimeDaFoto(img.src) ||
      container.querySelector(".linha2__1MJc1 span:last-child")
        ?.textContent?.trim();

    if (!time || !imagensPorTime?.[time]) return;

    const nomeNormalizado = normalizarNome(nome);

    const entrada = Object.entries(imagensPorTime[time]).find(
      ([nomeJogador]) =>
        normalizarNome(nomeJogador) === nomeNormalizado
    );

    if (!entrada) return;

    const [, novaFoto] = entrada;

    // 🔥 só troca se for silhueta (cards) ou foto diferente
    if (isSilhueta(img.src) || img.src !== novaFoto) {
      img.src = novaFoto;
      img.style.objectFit = "cover";
    }
  });
}

/***********************
 * Visual fix (cards)
 ***********************/
function ajustarFotoCard() {
  document.querySelectorAll("img.atleta__3V7v4").forEach(img => {
    const wrapper = img.closest("[class*='foto-wrapper']");
    if (!wrapper) return;

    wrapper.style.borderRadius = "50%";
    wrapper.style.overflow = "hidden";

    img.style.borderRadius = "50%";
    img.style.width = "56px";
    img.style.height = "56px";
    img.style.objectFit = "cover";
    img.style.background = "white";
  });
}

/***********************
 * Main
 ***********************/
function replaceImages() {
  replacePlayerPhotos();
  ajustarFotoCard();
  replaceShieldIcons();
}

/***********************
 * Runner (SPA safe)
 ***********************/
let running = false;

setInterval(() => {
  if (running) return;
  running = true;
  try {
    replaceImages();
  } finally {
    running = false;
  }
}, 300);
